"""Serial policy reduction: derivative construction, minimisation, numbering.

The compiler turns a parsed policy (see :mod:`syntax`) into the canonical live
state image described by the contract:

* the language is ``union(allow rules)`` minus ``union(drop rules)`` over every
  finite sequence of registered services;
* states are Myhill-Nerode residuals of that language, i.e. the minimal
  deterministic complete machine;
* residuals that cannot reach an allowed sequence are removed and every
  transition leading there becomes ``DENY``;
* retained residuals are numbered by breadth first discovery from ``START``,
  scanning outgoing columns in increasing service label order.

Everything runs on the CPU with plain Python containers, deterministically and
without spawning workers.
"""
from syntax import (MATCH, STARTSWITH, ENDSWITH, CONTAINS, AND, OR, NOT,
                    ALLOW, DROP)

__all__ = ['DENY', 'MAX_ROWS', 'ImageTooBig', 'CompiledImage', 'compile_rules']

DENY = 4294967295
MAX_ROWS = 8192

# Guards.  A stage whose machine exceeds MAX_ROWS rows is rejected, and the
# derivative exploration is bounded so that a hostile policy can never exhaust
# the CPU/maintenance window before that verdict is reached.
MAX_STATES = 131072
MAX_NODES = 524288

# Node identities.
FALSE = 0
TRUE = 1
K_FALSE = -1
K_TRUE = -2
K_LEAF = 2
K_NLEAF = 3
K_AND = 4
K_OR = 5

# Atom kinds.
_KINDS = (MATCH, STARTSWITH, ENDSWITH, CONTAINS)


class ImageTooBig(Exception):
    """The canonical machine has more than MAX_ROWS live residuals."""


class CompiledImage(object):
    """Serial export of one immutable map image."""

    __slots__ = ('accept', 'rows', 'cells')

    def __init__(self, accept, rows, cells):
        self.accept = accept
        self.rows = rows
        self.cells = cells

    def as_object(self):
        return {'accept': self.accept, 'rows': self.rows}


class _Atom(object):
    """Complete deterministic machine of one predicate atom."""

    __slots__ = ('delta', 'acc', 'all', 'empty')

    def __init__(self, delta, acc):
        self.delta = delta
        self.acc = acc
        n = len(delta)
        # residual(state) == Sigma*  /  residual(state) == {}
        every = [False] * n
        none = [False] * n
        for _ in range(n + 1):
            changed = False
            for s in range(n):
                row = delta[s]
                e = acc[s]
                d = not acc[s]
                for t in row:
                    if not every[t]:
                        e = False
                    if not none[t]:
                        d = False
                if e != every[s]:
                    every[s] = True
                    changed = True
                if d != none[s]:
                    none[s] = True
                    changed = True
            if not changed:
                break
        self.all = every
        self.empty = none


def _build_atom(kind, cols, sigma):
    """Complete DFA of one atom over the column alphabet ``range(sigma)``."""
    n = len(cols)
    if kind == MATCH:
        dead = n + 1
        delta = []
        for i in range(n):
            delta.append(tuple(i + 1 if c == cols[i] else dead for c in range(sigma)))
        delta.append((dead,) * sigma)
        delta.append((dead,) * sigma)
        acc = [i == n for i in range(n + 2)]
        return _Atom(delta, acc)
    if kind == STARTSWITH:
        if n == 0:
            return _Atom([(0,) * sigma], [True])
        dead = n + 1
        delta = []
        for i in range(n):
            delta.append(tuple(i + 1 if c == cols[i] else dead for c in range(sigma)))
        delta.append((n,) * sigma)
        delta.append((dead,) * sigma)
        acc = [i == n for i in range(n + 2)]
        return _Atom(delta, acc)
    if n == 0:
        return _Atom([(0,) * sigma], [True])
    # Failure function of the pattern, used by endswith/contains.
    fail = [0] * n
    length = 0
    i = 1
    while i < n:
        if cols[i] == cols[length]:
            length += 1
            fail[i] = length
            i += 1
        elif length:
            length = fail[length - 1]
        else:
            fail[i] = 0
            i += 1

    def nxt(state, c):
        while True:
            if state < n and cols[state] == c:
                return state + 1
            if state == 0:
                return 0
            state = fail[state - 1]

    if kind == ENDSWITH:
        delta = [tuple(nxt(s, c) for c in range(sigma)) for s in range(n + 1)]
        acc = [s == n for s in range(n + 1)]
        return _Atom(delta, acc)
    delta = [tuple(nxt(s, c) for c in range(sigma)) for s in range(n)]
    delta.append((n,) * sigma)
    acc = [s == n for s in range(n + 1)]
    return _Atom(delta, acc)


class _Builder(object):
    """Hash consed residual expressions plus derivative exploration."""

    def __init__(self, sigma):
        self.sigma = sigma
        self.atoms = []
        self.atom_cache = {}
        self.kind = [K_FALSE, K_TRUE]
        self.kids = [(), ()]
        self.nully = [False, True]
        self.intern = {}
        self.negmemo = {}
        self.dmemo = {}

    # -- atoms -----------------------------------------------------------
    def atom(self, kind, cols):
        key = (kind, cols)
        index = self.atom_cache.get(key)
        if index is None:
            index = len(self.atoms)
            self.atoms.append(_build_atom(kind, cols, self.sigma))
            self.atom_cache[key] = index
        return index

    # -- hash consed nodes ----------------------------------------------
    def _new(self, kind, kids, nully):
        node = len(self.kind)
        if node > MAX_NODES:
            raise ImageTooBig('nodes')
        self.kind.append(kind)
        self.kids.append(kids)
        self.nully.append(nully)
        self.intern[(kind, kids)] = node
        return node

    def leaf(self, index, state, negated):
        atom = self.atoms[index]
        if atom.empty[state]:
            return TRUE if negated else FALSE
        if atom.all[state]:
            return FALSE if negated else TRUE
        kind = K_NLEAF if negated else K_LEAF
        key = (kind, (index, state))
        node = self.intern.get(key)
        if node is None:
            acc = atom.acc[state]
            node = self._new(kind, (index, state), (not acc) if negated else acc)
        return node

    def negate(self, node):
        got = self.negmemo.get(node)
        if got is not None:
            return got
        kind = self.kind[node]
        if kind == K_FALSE:
            got = TRUE
        elif kind == K_TRUE:
            got = FALSE
        elif kind == K_LEAF:
            index, state = self.kids[node]
            got = self.leaf(index, state, True)
        elif kind == K_NLEAF:
            index, state = self.kids[node]
            got = self.leaf(index, state, False)
        elif kind == K_AND:
            got = self.mk_or([self.negate(c) for c in self.kids[node]])
        else:
            got = self.mk_and([self.negate(c) for c in self.kids[node]])
        self.negmemo[node] = got
        return got

    def mk_and(self, children):
        flat = []
        for child in children:
            kind = self.kind[child]
            if kind == K_FALSE:
                return FALSE
            if kind == K_TRUE:
                continue
            if kind == K_AND:
                flat.extend(self.kids[child])
            else:
                flat.append(child)
        if not flat:
            return TRUE
        flat = sorted(set(flat))
        if len(flat) == 1:
            return flat[0]
        kids = tuple(flat)
        node = self.intern.get((K_AND, kids))
        if node is not None:
            return node
        nully = True
        for child in kids:
            if not self.nully[child]:
                nully = False
                break
        return self._new(K_AND, kids, nully)

    def mk_or(self, children):
        flat = []
        for child in children:
            kind = self.kind[child]
            if kind == K_TRUE:
                return TRUE
            if kind == K_FALSE:
                continue
            if kind == K_OR:
                flat.extend(self.kids[child])
            else:
                flat.append(child)
        if not flat:
            return FALSE
        flat = sorted(set(flat))
        if len(flat) == 1:
            return flat[0]
        kids = tuple(flat)
        node = self.intern.get((K_OR, kids))
        if node is not None:
            return node
        nully = False
        for child in kids:
            if self.nully[child]:
                nully = True
                break
        return self._new(K_OR, kids, nully)

    # -- expression translation -----------------------------------------
    def translate(self, node, cols_of):
        kind = node[0]
        if kind <= CONTAINS:
            path = node[1]
            if path:
                cols = tuple([cols_of[i] for i in path])
            else:
                cols = ()
            return self.leaf(self.atom(kind, cols), 0, False)
        if kind == AND:
            return self.mk_and((self.translate(node[1], cols_of),
                               self.translate(node[2], cols_of)))
        if kind == OR:
            return self.mk_or((self.translate(node[1], cols_of),
                               self.translate(node[2], cols_of)))
        return self.negate(self.translate(node[1], cols_of))

    # -- derivatives -----------------------------------------------------
    def derive(self, node, c):
        key = node * self.sigma + c
        got = self.dmemo.get(key)
        if got is not None:
            return got
        kind = self.kind[node]
        if kind == K_LEAF:
            index, state = self.kids[node]
            got = self.leaf(index, self.atoms[index].delta[state][c], False)
        elif kind == K_NLEAF:
            index, state = self.kids[node]
            got = self.leaf(index, self.atoms[index].delta[state][c], True)
        elif kind == K_AND:
            got = self.mk_and([self.derive(child, c) for child in self.kids[node]])
        elif kind == K_OR:
            got = self.mk_or([self.derive(child, c) for child in self.kids[node]])
        else:
            got = node
        self.dmemo[key] = got
        return got


def _explore(root, builder):
    """Breadth first derivative exploration of the residual automaton."""
    sigma = builder.sigma
    states = [root]
    index = {root: 0}
    trans = []
    acc = [builder.nully[root]]
    derive = builder.derive
    nully = builder.nully
    current = 0
    total = 1
    while current < total:
        node = states[current]
        current += 1
        row = []
        append = row.append
        for c in range(sigma):
            target = derive(node, c)
            got = index.get(target)
            if got is None:
                got = total
                total += 1
                if total > MAX_STATES:
                    raise ImageTooBig('states')
                index[target] = got
                states.append(target)
                acc.append(nully[target])
            append(got)
        trans.append(tuple(row))
    return trans, acc


def _coreachable(trans, acc, n):
    """States from which some accepting state is reachable (residual != {})."""
    sigma = len(trans[0]) if n else 0
    degree = [0] * n
    for row in trans:
        for target in row:
            degree[target] += 1
    start = [0] * (n + 1)
    running = 0
    for s in range(n):
        start[s] = running
        running += degree[s]
    start[n] = running
    rev = [0] * running
    pos = start[:]
    for s, row in enumerate(trans):
        for target in row:
            rev[pos[target]] = s
            pos[target] += 1
    live = bytearray(n)
    stack = [s for s in range(n) if acc[s]]
    for s in stack:
        live[s] = 1
    while stack:
        s = stack.pop()
        for i in range(start[s], start[s + 1]):
            p = rev[i]
            if not live[p]:
                live[p] = 1
                stack.append(p)
    return live


def _contract(trans, acc, live, n):
    """Collapse every dead residual into a single state (index 0)."""
    mapping = [0] * n
    states = [0]
    acc2 = [False]
    trans2 = [None]
    for s in range(n):
        if live[s]:
            mapping[s] = len(states)
            states.append(s)
            acc2.append(acc[s])
            trans2.append(None)
    size = len(states)
    for i in range(1, size):
        row = trans[states[i]]
        trans2[i] = tuple(mapping[t] if live[t] else 0 for t in row)
    dead_row = (0,) * (len(trans[0]) if n else 0)
    trans2[0] = dead_row
    start = mapping[0]
    return trans2, acc2, start


def _minimize(trans, acc, n):
    """Partition refinement; returns the class id of every state."""
    classes = [1 if a else 0 for a in acc]
    get = classes.__getitem__
    while True:
        groups = {}
        for s in range(n):
            key = (classes[s], tuple(map(get, trans[s])))
            bucket = groups.get(key)
            if bucket is None:
                groups[key] = [s]
            else:
                bucket.append(s)
        if len(groups) == len(set(classes)):
            break
        classes = [0] * n
        for number, bucket in enumerate(groups.values()):
            for s in bucket:
                classes[s] = number
        get = classes.__getitem__
    return classes


def compile_rules(rules, cols_of, sigma):
    """Compile parsed rules into a canonical :class:`CompiledImage`."""
    builder = _Builder(sigma)
    allow = []
    drop = []
    for node, action in rules:
        target = allow if action == ALLOW else drop
        target.append(builder.translate(node, cols_of))
    root = builder.mk_and((builder.mk_or(allow),
                           builder.negate(builder.mk_or(drop))))
    trans, acc = _explore(root, builder)
    n = len(trans)
    live = _coreachable(trans, acc, n)
    trans, acc, start = _contract(trans, acc, live, n)
    n = len(trans)
    classes = _minimize(trans, acc, n)
    count = max(classes) + 1 if n else 0
    mtrans = [None] * count
    macc = [False] * count
    for s in range(n):
        c = classes[s]
        if mtrans[c] is None:
            mtrans[c] = tuple(classes[t] for t in trans[s])
            macc[c] = acc[s]
    dead = classes[0]
    start = classes[start]
    # Breadth first numbering, columns already in increasing label order.
    order = [start]
    index = {start: 0}
    head = 0
    while head < len(order):
        c = order[head]
        head += 1
        for t in mtrans[c]:
            if t != dead and t not in index:
                index[t] = len(order)
                order.append(t)
    size = len(order)
    if size > MAX_ROWS:
        raise ImageTooBig('rows')
    if size == 1 and dead not in index:
        # START only (empty or fully dead language).
        pass
    rows = []
    cells = 0
    for c in order:
        row = []
        for t in mtrans[c]:
            if t == dead:
                row.append(DENY)
            else:
                got = index[t]
                row.append(got)
                cells += 1
        rows.append(row)
    accept = [bool(macc[c]) for c in order]
    return CompiledImage(accept, rows, cells)
